style.css:
@-moz-document domain("google.com") {
/* -------------------- IMAGE SETTINGS -------------------- */
  /* To change the image, update the URL in this root variable only */
  :root {
    --fdf-image: url("https://userstyles.org");
  }

  /* -------------------- REMOVING UNNECESSARY BUTTONS -------------------- */
  /* Hide footer and unneeded panels on the homepage */
  .o3j99.n1xJcf.Ne6nSd,
  .FPdoLc.lJ9FBc,
  .o3j99.c93Gbe,
  .fbar {
    display: none !important;
  }

  /* -------------------- BOTTOM RIGHT BACKGROUND (On Results Page) -------------------- */
  body, #main {
    background: var(--fdf-image) 95% 95% no-repeat !important;
    background-attachment: fixed !important;
    background-size: 250px auto !important; /* Controls Hestia's size in the corner */
  }

  /* -------------------- HOMEPAGE LOGO REPLACEMENT -------------------- */
  /* Hide the default Google logo image safely */
  .lnXdpd, 
  .k1zZ6c, 
  img[alt="Google"],
  #hplogo {
    opacity: 0 !important;
    visibility: hidden !important;
  }

  /* Apply Hestia background animation to the parent logo container */
  .LLD4me {
    background: var(--fdf-image) center center no-repeat !important;
    background-size: contain !important;
    max-height: 250px !important; /* Restricts height so search buttons do not move */
  }

  /* -------------------- TOP LEFT LOGO (On Search Results Page) -------------------- */
  /* Hide the small Google logo in search results */
  .logo img, 
  #logo img, 
  .chunk img {
    opacity: 0 !important;
  }

  /* Inject the custom animated logo instead */
  .logo, 
  #logo, 
  .chunk {
    background: var(--fdf-image) left center no-repeat !important;
    background-size: contain !important;
    min-width: 150px !important;
  }
}
